SET LOCAL search_path TO productionrunner, pg_catalog;

CREATE TABLE IF NOT EXISTS part_catalog_controls (
 tenant_id INTEGER NOT NULL,part_id TEXT PRIMARY KEY,archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),version INTEGER NOT NULL DEFAULT 0,
 FOREIGN KEY(tenant_id,part_id) REFERENCES part_revisions(tenant_id,id)
);
CREATE TABLE IF NOT EXISTS part_catalog_changes (
 id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id INTEGER NOT NULL,part_id TEXT NOT NULL,actor_id INTEGER NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL,
 FOREIGN KEY(tenant_id,part_id) REFERENCES part_revisions(tenant_id,id),
 FOREIGN KEY(tenant_id,actor_id) REFERENCES memberships(tenant_id,user_id)
);
CREATE INDEX IF NOT EXISTS part_catalog_change_part ON part_catalog_changes(tenant_id,part_id,id);
CREATE INDEX IF NOT EXISTS part_catalog_change_actor ON part_catalog_changes(tenant_id,actor_id);
CREATE OR REPLACE FUNCTION part_revision_no_update_fn() RETURNS trigger LANGUAGE plpgsql SET search_path TO productionrunner, pg_catalog AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id OR (EXISTS(SELECT 1 FROM ticket_drawings WHERE tenant_id=OLD.tenant_id AND part_revision_id=OLD.id) OR EXISTS(SELECT 1 FROM tickets WHERE tenant_id=OLD.tenant_id AND pn=OLD.pn AND revision=OLD.revision) OR EXISTS(SELECT 1 FROM intake_requests WHERE tenant_id=OLD.tenant_id AND (part_id=OLD.id OR (pn=OLD.pn AND revision=OLD.revision))) OR EXISTS(SELECT 1 FROM part_plan_templates WHERE tenant_id=OLD.tenant_id AND part_id=OLD.id)) OR (EXISTS(SELECT 1 FROM ticket_drawings WHERE tenant_id=NEW.tenant_id AND part_revision_id=NEW.id) OR EXISTS(SELECT 1 FROM tickets WHERE tenant_id=NEW.tenant_id AND pn=NEW.pn AND revision=NEW.revision) OR EXISTS(SELECT 1 FROM intake_requests WHERE tenant_id=NEW.tenant_id AND (part_id=NEW.id OR (pn=NEW.pn AND revision=NEW.revision))) OR EXISTS(SELECT 1 FROM part_plan_templates WHERE tenant_id=NEW.tenant_id AND part_id=NEW.id)) THEN RAISE EXCEPTION 'Used part revisions cannot be edited' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION part_dxf_no_update_fn() RETURNS trigger LANGUAGE plpgsql SET search_path TO productionrunner, pg_catalog AS $$ BEGIN IF NEW.part_revision_id<>OLD.part_revision_id OR NEW.tenant_id<>OLD.tenant_id OR EXISTS(SELECT 1 FROM part_revisions P WHERE P.tenant_id=OLD.tenant_id AND P.id=OLD.part_revision_id AND (EXISTS(SELECT 1 FROM ticket_drawings WHERE tenant_id=P.tenant_id AND part_revision_id=P.id) OR EXISTS(SELECT 1 FROM tickets WHERE tenant_id=P.tenant_id AND pn=P.pn AND revision=P.revision) OR EXISTS(SELECT 1 FROM intake_requests WHERE tenant_id=P.tenant_id AND (part_id=P.id OR (pn=P.pn AND revision=P.revision))) OR EXISTS(SELECT 1 FROM part_plan_templates WHERE tenant_id=P.tenant_id AND part_id=P.id))) THEN RAISE EXCEPTION 'Used DXF revisions cannot be edited' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER part_catalog_changes_immutable BEFORE UPDATE OR DELETE ON part_catalog_changes FOR EACH ROW EXECUTE FUNCTION part_event_no_update_fn();
GRANT SELECT,INSERT ON part_catalog_controls TO productionrunner_runtime;
GRANT UPDATE(archived,version) ON part_catalog_controls TO productionrunner_runtime;
GRANT SELECT,INSERT ON part_catalog_changes TO productionrunner_runtime;
GRANT USAGE,SELECT ON SEQUENCE part_catalog_changes_id_seq TO productionrunner_runtime;
GRANT UPDATE(pn,revision,description,drawing_pdf,drawing_url,sha256,object_key,object_size) ON part_revisions TO productionrunner_runtime;
GRANT UPDATE(content,sha256,uploaded_by,uploaded_at,object_key,object_size) ON part_dxf TO productionrunner_runtime;
